/**
 * Adapts the AndroidManifest.xml generated by React Native:
 *  - permissions (network, microphone, camera, audio)
 *  - an intent filter for the "duetto://channel" deep link, so that
 *    touching the notification opens Duetto straight away
 *
 * Idempotent: it can be run again without duplicating anything.
 */
const fs = require('fs');
const path = require('path');

const manifestPath = path.join(
  __dirname, '..', 'android', 'app', 'src', 'main', 'AndroidManifest.xml',
);

if (!fs.existsSync(manifestPath)) {
  console.log('AndroidManifest.xml not found: run bootstrap.sh first');
  process.exit(0);
}

let xml = fs.readFileSync(manifestPath, 'utf8');
let changes = 0;

// --- Permissions ------------------------------------------------------------
const permissions = [
  'android.permission.INTERNET',
  'android.permission.ACCESS_NETWORK_STATE',
  'android.permission.RECORD_AUDIO',
  'android.permission.CAMERA',
  'android.permission.MODIFY_AUDIO_SETTINGS',
  'android.permission.BLUETOOTH_CONNECT', // BT earphones
  // Staying in the channel in the background / with the screen off.
  // The service is declared by the duetto-platform module and its
  // permissions come from the manifest merge; they are repeated here so
  // that they can be seen by reading the app's manifest.
  'android.permission.FOREGROUND_SERVICE',
  'android.permission.FOREGROUND_SERVICE_MICROPHONE',
  'android.permission.FOREGROUND_SERVICE_CAMERA',
  'android.permission.WAKE_LOCK',
  'android.permission.POST_NOTIFICATIONS',
  'android.permission.VIBRATE', // the "Call" knock
];

for (const p of permissions) {
  if (!xml.includes(`android:name="${p}"`)) {
    xml = xml.replace(/<manifest([^>]*)>/, (m) => `${m}\n    <uses-permission android:name="${p}" />`);
    changes++;
  }
}

// --- Features that are not required -----------------------------------------
const features = ['android.hardware.camera', 'android.hardware.microphone'];
for (const f of features) {
  if (!xml.includes(`<uses-feature android:name="${f}"`)) {
    xml = xml.replace(
      /<manifest([^>]*)>/,
      (m) => `${m}\n    <uses-feature android:name="${f}" android:required="false" />`,
    );
    changes++;
  }
}

// --- MainActivity: deep link + launchMode ----------------------------------
const activityRe = /<activity\b[^>]*android:name="\.MainActivity"[^>]*>/;
const activityMatch = xml.match(activityRe);

if (!activityMatch) {
  console.warn('Warning: MainActivity not found, deep link not added.');
} else {
  // launchMode singleTask: without it, touching the notification would
  // open a second instance of the app instead of bringing the one
  // already open to the front. If the attribute is there it has to be
  // REPLACED: duplicating it makes the build fail.
  let tag = activityMatch[0];
  if (/android:launchMode="[^"]*"/.test(tag)) {
    if (!/android:launchMode="singleTask"/.test(tag)) {
      tag = tag.replace(/android:launchMode="[^"]*"/, 'android:launchMode="singleTask"');
      changes++;
    }
  } else {
    tag = tag.replace(
      /android:name="\.MainActivity"/,
      'android:name=".MainActivity"\n        android:launchMode="singleTask"',
    );
    changes++;
  }
  // Picture-in-Picture: the Back key puts the app into the little
  // window instead of taking you out of it.
  if (!/android:supportsPictureInPicture=/.test(tag)) {
    tag = tag.replace(
      /android:name="\.MainActivity"/,
      'android:name=".MainActivity"\n        android:supportsPictureInPicture="true"',
    );
    changes++;
  }

  /**
   * Configuration changes we deal with ourselves.
   *
   * If the activity does not declare them, Android REBUILDS it from
   * scratch: and rebuilding the activity means putting the whole
   * interface up again, that is tearing the previous one down - with
   * everything that brings with it. PiP is the obvious case: without
   * `screenSize` the little window recreated the activity and the
   * conversation dropped.
   *
   * The other four were taught by a night in August: at 00:45, with the
   * other person's phone down to 28% and nobody awake to touch it, the
   * interface started again from scratch. At 30% the power saving comes
   * in, and that changes things like colour depth or screen density.
   * They were not declared, so the window was rebuilt, the old
   * interface torn down, and in that teardown went the service that
   * kept the presence alive: a quarter of an hour later Motorola's
   * manager took the process.
   *
   * With them declared, nothing is rebuilt for those changes any more:
   * React Native redraws by itself, which is what it does at every
   * rotation.
   */
  const neededConfig = [
    'screenSize', 'smallestScreenSize', 'screenLayout', 'orientation',
    'colorMode', 'density', 'fontScale', 'locale', 'layoutDirection',
  ];
  const configMatch = tag.match(/android:configChanges="([^"]*)"/);
  if (configMatch) {
    const have = configMatch[1].split('|').filter(Boolean);
    const missing = neededConfig.filter((c) => !have.includes(c));
    if (missing.length > 0) {
      tag = tag.replace(
        /android:configChanges="[^"]*"/,
        `android:configChanges="${[...have, ...missing].join('|')}"`,
      );
      changes++;
    }
  } else {
    tag = tag.replace(
      /android:name="\.MainActivity"/,
      `android:name=".MainActivity"\n        android:configChanges="${neededConfig.join('|')}"`,
    );
    changes++;
  }

  if (tag !== activityMatch[0]) {
    xml = xml.replace(activityRe, () => tag);
  }

  // The deep link, put inside THE MainActivity (after its first
  // intent-filter), not after the document's first intent-filter.
  if (!xml.includes('android:scheme="duetto"')) {
    const activityAt = xml.search(activityRe);
    const closeTag = '</intent-filter>';
    const filterEnd = xml.indexOf(closeTag, activityAt);
    const activityEnd = xml.indexOf('</activity>', activityAt);

    if (filterEnd !== -1 && (activityEnd === -1 || filterEnd < activityEnd)) {
      const at = filterEnd + closeTag.length;
      const deepLink = `
        <intent-filter>
            <action android:name="android.intent.action.VIEW" />
            <category android:name="android.intent.category.DEFAULT" />
            <category android:name="android.intent.category.BROWSABLE" />
            <data android:scheme="duetto" android:host="channel" />
        </intent-filter>`;
      xml = xml.slice(0, at) + deepLink + xml.slice(at);
      changes++;
    } else {
      console.warn('Warning: the MainActivity intent-filter was not found.');
    }
  }
}

fs.writeFileSync(manifestPath, xml);
console.log(`Manifest updated (${changes} changes).`);
